#!/bin/bash
# vibe-crew cache hook (generated by claude-team-init; template: src/generators/cache-hook.sh)
#
# The Stop hook (`stop-check`) is the only builder. Agents call `run build` / `run test`:
# a digest cached for the current tree is returned instantly, otherwise the command
# runs once and its digest is cached.
# Key:    <repo>-<cmd>-<HEAD short sha>-<8-char hash of `git diff HEAD` + untracked files>
# Digest: status line, error count, first 40 error lines. Never raw logs, never secrets.
# Store:  local files under .git/vibe-crew-cache, plus the remote cache server when
#         .claude/.cache-env sets FLYIO_URL + FLYIO_TOKEN. Remote is best-effort:
#         unreachable or a stale token just means the command runs.
set -u

BUILD_CMD=__BUILD_CMD__
TEST_CMD=__TEST_CMD__
SRC_EXT=__SRC_EXT__ # source-file extensions for this stack (extended regex)
TTL=86400
MAX_LOCAL=50

ROOT=$(git rev-parse --show-toplevel 2>/dev/null || pwd)
cd "$ROOT" || exit 0
if GIT_COMMON=$(git rev-parse --git-common-dir 2>/dev/null); then
  GIT_COMMON=$(cd "$GIT_COMMON" && pwd)
  LOCAL_DIR="$GIT_COMMON/vibe-crew-cache" # shared by every worktree of this clone
  MAIN_ROOT=$(dirname "$GIT_COMMON")
else
  LOCAL_DIR="$ROOT/.claude/cache"
  MAIN_ROOT=$ROOT
fi
FLYIO_URL="" FLYIO_TOKEN=""
for f in "$ROOT/.claude/.cache-env" "$MAIN_ROOT/.claude/.cache-env"; do
  [ -f "$f" ] && { . "$f"; break; }
done
REMOTE_DOWN=0
REPO=$(basename "$MAIN_ROOT" | tr -c 'A-Za-z0-9._\n-' '-')

# ─── keys ────────────────────────────────────────────────────────────────────
tree_hash() {
  {
    git diff HEAD --binary 2>/dev/null
    git ls-files -o --exclude-standard -z 2>/dev/null | while IFS= read -r -d '' f; do
      printf '%s %s\n' "$f" "$(git hash-object -- "$f" 2>/dev/null)"
    done
  } | git hash-object --stdin | cut -c1-8
}
make_key() {
  local name; name=$(printf '%s' "$1" | tr -c 'A-Za-z0-9_-' '-')
  printf '%s-%s-%s-%s' "$REPO" "$name" "$(git rev-parse --short HEAD 2>/dev/null || echo nohead)" "$(tree_hash)"
}

# ─── local store ─────────────────────────────────────────────────────────────
local_get() {
  local f="$LOCAL_DIR/$1"
  [ -f "$f" ] && [ -z "$(find "$f" -mmin +$((TTL / 60)) 2>/dev/null)" ] && cat "$f"
}
local_set() { # key digest name
  mkdir -p "$LOCAL_DIR" || return 0
  printf '%s\n' "$2" >"$LOCAL_DIR/$1.tmp" && mv "$LOCAL_DIR/$1.tmp" "$LOCAL_DIR/$1"
  cp "$LOCAL_DIR/$1" "$LOCAL_DIR/last-$3"
  # ponytail: newest-50 LRU by mtime; plenty for one clone's recent trees
  ls -t "$LOCAL_DIR" | grep -v '^last-' | tail -n +$((MAX_LOCAL + 1)) | while read -r old; do rm -f "$LOCAL_DIR/$old"; done
}

# ─── remote store (best-effort) ──────────────────────────────────────────────
remote_on() { [ -n "$FLYIO_URL" ] && [ -n "$FLYIO_TOKEN" ] && [ "$REMOTE_DOWN" = 0 ]; }
rcurl() { curl -s --connect-timeout 3 --max-time 5 -H "Authorization: Bearer $FLYIO_TOKEN" "$@"; }
remote_get() { # key -> sets HIT. Not run in a subshell, so REMOTE_DOWN sticks for the later write.
  remote_on || return 1
  local r code b64
  r=$(rcurl -w '\n%{http_code}' "$FLYIO_URL/mcp/cache-get/$1") || { REMOTE_DOWN=1; return 1; }
  code=${r##*$'\n'}
  [ "$code" = 200 ] || { REMOTE_DOWN=1; return 1; } # stale token / server error: stop talking to it
  b64=$(printf '%s' "${r%$'\n'*}" | sed -n 's/.*"b64":"\([A-Za-z0-9+/=]*\)".*/\1/p')
  [ -n "$b64" ] || return 1
  HIT=$(printf '%s' "$b64" | base64 -d 2>/dev/null) && [ -n "$HIT" ]
}
remote_set() { # key status errors digest original_bytes
  remote_on || return 0
  local b64 code
  b64=$(printf '%s' "$4" | base64 | tr -d '\n')
  code=$(printf '{"key":"%s","ttl":%s,"original_bytes":%s,"value":{"status":"%s","errors":%s,"b64":"%s"}}' \
    "$1" "$TTL" "${5:-0}" "$2" "${3:-0}" "$b64" |
    rcurl -o /dev/null -w '%{http_code}' -X POST -H 'Content-Type: application/json' --data-binary @- "$FLYIO_URL/mcp/cache-set")
  case "$code" in 2*) ;; *) echo "vibe-crew: remote cache write failed (HTTP ${code:-none}); result kept locally" >&2 ;; esac
}
lookup() { # key name -> sets HIT
  HIT=$(local_get "$1") && return 0
  remote_get "$1" || return 1
  local_set "$1" "$HIT" "$2"
}

# ─── digest ──────────────────────────────────────────────────────────────────
redact() {
  sed -E \
    -e 's/([A-Za-z_]*([Kk][Ee][Yy]|[Tt][Oo][Kk][Ee][Nn]|[Ss][Ee][Cc][Rr][Ee][Tt]|[Pp][Aa][Ss][Ss][Ww][Oo][Rr][Dd])[A-Za-z_]*["'"'"']?[[:space:]]*[=:][[:space:]]*["'"'"']?)[^[:space:]"'"'"',]+/\1[redacted]/g' \
    -e 's/(sk|pk|rk)_(live|test)_[A-Za-z0-9]+/[redacted]/g' \
    -e 's/gh[pousr]_[A-Za-z0-9]{20,}/[redacted]/g' \
    -e 's/eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9._-]+/[redacted]/g'
}
make_digest() { # name rc logfile key
  local status=PASS errors=0 lines
  if [ "$2" != 0 ]; then
    status=FAIL
    errors=$(grep -ciE 'error' "$3")
    lines=$(grep -iE -B1 -A1 'error|fail|panic|exception|cannot find|not found' "$3" | grep -v '^--$' | head -40)
    [ -n "$lines" ] || lines=$(tail -40 "$3")
  else
    lines=$(tail -3 "$3")
  fi
  printf '%s %s exit=%s errors=%s key=%s\n' "$1" "$status" "$2" "$errors" "$4"
  printf '%s\n' "$lines" | redact
}

# ─── commands ────────────────────────────────────────────────────────────────
cmd_run() { # name [-- cmd...]   exit 0 = pass, 1 = fail
  local name=$1 cmd key d log rc first
  shift
  [ "${1:-}" = -- ] && shift
  cmd="$*"
  if [ -z "$cmd" ]; then
    case "$name" in build) cmd=$BUILD_CMD ;; test) cmd=$TEST_CMD ;; esac
  fi
  [ -n "$cmd" ] || { echo "$name: no command configured"; return 0; }
  key=$(make_key "$name")
  if lookup "$key" "$name"; then
    echo "cache hit: $key (skipped $name)"
    printf '%s\n' "$HIT"
    first=${HIT%%$'\n'*}
    case "$first" in *" PASS "*) return 0 ;; *) return 1 ;; esac
  fi
  log=$(mktemp)
  (eval "$cmd") >"$log" 2>&1
  rc=$?
  d=$(make_digest "$name" "$rc" "$log" "$key")
  local_set "$key" "$d" "$name"
  first=${d%%$'\n'*}
  remote_set "$key" "$([ "$rc" = 0 ] && echo pass || echo fail)" "$(printf '%s' "$first" | sed -n 's/.* errors=\([0-9]*\).*/\1/p')" "$d" "$(wc -c <"$log" | tr -d ' ')"
  rm -f "$log"
  printf '%s\n' "$d"
  [ "$rc" = 0 ]
}

# Stop hook: build once per turn, only when uncommitted changes touch real source code.
cmd_stop_check() {
  local payload changed code_lines out
  payload=$(cat 2>/dev/null || true)
  case "$payload" in *'"stop_hook_active":true'* | *'"stop_hook_active": true'*) return 0 ;; esac # already blocked once this turn
  [ -n "$BUILD_CMD" ] || return 0
  changed=$({ git diff HEAD --name-only; git ls-files -o --exclude-standard; } 2>/dev/null | grep -E "\.($SRC_EXT)\$")
  [ -n "$changed" ] || return 0 # docs / config / markdown only
  if ! git ls-files -o --exclude-standard 2>/dev/null | grep -qE "\.($SRC_EXT)\$"; then
    code_lines=$(printf '%s\n' "$changed" | tr '\n' '\0' | xargs -0 git diff HEAD -U0 -- 2>/dev/null |
      grep -E '^[+-]' | grep -vE '^(\+\+\+|---)( |$)' | grep -vE '^[+-][[:space:]]*(//|#|\*|/\*|--|$)')
    [ -n "$code_lines" ] || return 0 # comment / blank-line-only edits
  fi
  out=$(cmd_run build 2>/dev/null) && return 0
  case "$out" in "cache hit:"*) return 0 ;; esac # this failure was already reported for this tree
  printf '%s\n' "$out" | head -20 >&2
  return 2
}

cmd_base() { # merge-base with the default branch; diff against it = branch commits + uncommitted work
  local def
  def=$(git symbolic-ref -q --short refs/remotes/origin/HEAD 2>/dev/null) || def=main
  git merge-base HEAD "$def" 2>/dev/null || git rev-parse HEAD 2>/dev/null
}

case "${1:-help}" in
  run) shift; cmd_run "$@" ;;
  stop-check) cmd_stop_check ;;
  base) cmd_base ;;
  key) make_key "${2:-build}"; echo ;;
  last) head -1 "$LOCAL_DIR/last-${2:-build}" 2>/dev/null || echo "${2:-build} ?" ;;
  set) # set <key> <json-value> [ttl]
    remote_on || { echo "remote cache not configured" >&2; exit 1; }
    printf '{"key":"%s","value":%s,"ttl":%s}' "$2" "$3" "${4:-$TTL}" |
      rcurl -X POST -H 'Content-Type: application/json' --data-binary @- "$FLYIO_URL/mcp/cache-set"; echo ;;
  get) remote_on && rcurl "$FLYIO_URL/mcp/cache-get/$2"; echo ;;
  health) remote_on && rcurl "$FLYIO_URL/health" | grep -q '"status":"ok"' && echo "Cache server healthy" || { echo "Cache server unavailable"; exit 1; } ;;
  *)
    cat <<'USAGE'
Usage: scripts/cache-hook.sh <command>
  run build|test [-- cmd...]  cached digest for this tree, else run once and cache it
  stop-check                  Stop-hook entry (reads hook JSON on stdin)
  base                        diff base: merge-base with the default branch
  key <name>                  print the cache key for the current tree
  last <name>                 status line of the most recent digest
  set <key> <json> [ttl] | get <key> | health   raw remote cache access
USAGE
    ;;
esac
